/**
 * Build a LOCAL _ds_bundle.js so cards can be rendered and checked on this machine.
 *
 * The real bundle is generated by the Claude Design app from the manifest's `components`
 * array, and is deliberately NOT pushed from here. This is a local stand-in whose only
 * job is to let a browser load the cards so we can see whether they render — a card whose
 * script throws produces an empty #root and shows up in the Design System pane as a blank
 * box, which reads as "the component is broken" rather than "the card is broken".
 *
 * Each component is wrapped in its own IIFE, so two components' top-level names never clash.
 * The shared helpers module, components/shared.js, is inlined once ahead of them, and each
 * component's import of it is dropped: its helpers are already in the enclosing scope.
 *
 *   node docs/build_bundle.js
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
// Pinned in the Auralis root package.json's devDependencies; `pnpm install` provides it.
const Babel = require('@babel/standalone');

const files = [];
for (const dir of fs.readdirSync(path.join(ROOT, 'components'))) {
  const d = path.join(ROOT, 'components', dir);
  if (!fs.statSync(d).isDirectory()) continue;
  for (const f of fs.readdirSync(d)) {
    if (f.endsWith('.jsx')) files.push({ name: f.slice(0, -4), file: path.join(d, f), rel: 'components/' + dir + '/' + f });
  }
}
files.sort((a, b) => a.name.localeCompare(b.name));

const parts = [];
const failed = [];
// React arrives as a UMD global, so an import is not only unnecessary, it is invalid here.
const stripModule = (src) => src
  .replace(/^\s*import\s+[^;]+;\s*$/gm, '')
  .replace(/^export\s+function\s+/gm, 'function ')
  .replace(/^export\s+(const|let|var)\s+/gm, '$1 ');
const transform = (src, filename) => Babel.transform(src, { presets: [['react', { runtime: 'classic' }]], filename }).code;

let shared = '';
try {
  shared = transform(stripModule(fs.readFileSync(path.join(ROOT, 'components', 'shared.js'), 'utf8')), 'components/shared.js');
} catch (e) {
  failed.push({ rel: 'components/shared.js', message: String(e.message).split('\n')[0] });
}

for (const { name, file, rel } of files) {
  let src = fs.readFileSync(file, 'utf8');
  src = src.replace(/^\s*import\s*\{[^}]*\}\s*from\s*['"]\.\.\/shared\.js['"];?\s*$/gm, '');

  // SideSheet reaches ScrollArea with a real relative `import` rather than the NS() idiom.
  // Stripping it leaves the name undefined, so it becomes a thin forwarder that resolves off the
  // namespace at RENDER time: the module bodies run in alphabetical order, so anything resolved
  // eagerly could capture undefined.
  const shims = [];
  src = src.replace(/^\s*import\s*\{([^}]+)\}\s*from\s*['"]\.[^'"]*['"];?\s*$/gm, (_, names) => {
    for (const raw of names.split(',')) {
      const n = raw.trim().split(/\s+as\s+/).pop().trim();
      if (n) shims.push('var ' + n + ' = function(props){ var C = (window.SonoraDesignSystem_6c1435||{})['
        + JSON.stringify(n) + ']; return C ? React.createElement(C, props) : null; };');
    }
    return '';
  });

  src = stripModule(src);
  if (shims.length) src = shims.join('\n') + '\n' + src;
  try {
    const out = transform(src, rel);
    parts.push('DS[' + JSON.stringify(name) + '] = (function(){\n' + out + '\nreturn typeof ' + name + ' !== "undefined" ? ' + name + ' : undefined;\n})();');
  } catch (e) {
    failed.push({ rel, message: String(e.message).split('\n')[0] });
  }
}

const bundle =
  '/* LOCAL render-check bundle. Generated by docs/build_bundle.js. Not pushed to Claude Design. */\n' +
  '(function(){\n' +
  'var React = window.React;\n' +
  'var DS = window.SonoraDesignSystem_6c1435 = window.SonoraDesignSystem_6c1435 || {};\n' +
  shared + '\n\n' +
  parts.join('\n\n') + '\n})();\n';

fs.writeFileSync(path.join(ROOT, '_ds_bundle.js'), bundle);

for (const f of failed) console.log('  TRANSPILE FAIL  ' + f.rel + '  ' + f.message);
console.log('bundled ' + parts.length + '/' + files.length + ' components' + (failed.length ? '  (' + failed.length + ' FAILED)' : ''));
process.exit(failed.length ? 1 : 0);
